import { Component } from '@angular/core';
import { user } from 'src/app/models/user';
import { AuthService } from 'src/app/service/auth.service';
import { Router } from '@angular/router';
import { throwError } from 'rxjs';

@Component({
  selector: 'app-form-login',
  templateUrl: './form-login.html',
  styleUrls: ['./form-login.css']
})
export class FormLogin {
  email: string = '';
  password: string = ''
  loading = false;
  success = false;
  error = '';

  constructor(
    private readonly auth: AuthService,
    private readonly router: Router
  ) {}

  login() {
    console.log(this.email, this.password);
    if(!this.email || !this.password)
      throwError(() => new Error('Fill in all fields'));

    this.auth.login(this.email, this.password).subscribe({
      next: (user) => {
        this.loading = false;
        this.success = true;
        console.log("Login information for...", user);
        this.router.navigate(['/login']);
      },
      error: (err) => {
        this.loading = false;
        this.error = err.message || 'Failed to login';
        console.log('Login failed', this.error);
      }
     })
  }
}

<link rel="stylesheet" href="form-login.css">

<div class="login-div">
<div class="Login-container">
   <h1>Survey Login</h1>

   <form>
   <div class="form-group">
      <input [(ngModel)]="email" type="email" name="email"
      placeholder="Email" required />
   </div>

   <div class="form-group">
      <input [(ngModel)]="password" type="password" name="password"
      placeholder="Password" required />
   </div>

   <div class="button-group">
      <button (click)="login()" type="submit" class="btn-signin">Sign In</button>
      <a routerLink="/register">Dont have an account?</a>
   </div>

</form>
</div></div>
